#define SAMPLE_APP_CCVAL(x) SAMPLE_APP_FunctionCode_##x

enum SAMPLE_APP_FunctionCode_
{
    SAMPLE_APP_FunctionCode_NOOP           = 0,
    SAMPLE_APP_FunctionCode_RESET_COUNTERS = 1,
    SAMPLE_APP_FunctionCode_PROCESS        = 2,
